    // Clamp grid so all blocks are co-resident (required for the spin sync).
    int64_t maxResident = (int64_t)bpsm * (int64_t)numSMs;
    int64_t S = maxResident / R;
    if (S < 1) S = 1;
    int64_t Smax = (Ne + TPB - 1) / TPB;
    if (Smax < 1) Smax = 1;
    if (S > Smax) S = Smax;
    int64_t chunk = (Ne + S - 1) / S;
    chunk = ((chunk + TPB - 1) / TPB) * (int64_t)TPB;
    int64_t Seff = (Ne + chunk - 1) / chunk;
    dim3 grid((unsigned)Seff, (unsigned)R);
    dim3 block(TPB);
    kfn_fb<<<grid, block, 0, stream>>>(X, W, B, Y, d_sum, d_sumsq, d_count,
                                       Ne, chunk, N, eps);
  }
}

torch::Tensor layernorm_forward(torch::Tensor x,
                                c10::optional<torch::Tensor> weight,
                                c10::optional<torch::Tensor> bias,
                                std::vector<int64_t> normalized_shape,
                                double eps)
{
  TORCH_CHECK(x.is_cuda(), "x must be a CUDA tensor");
  TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");
  const int64_t ndim = x.dim();
  const int64_t nn = (int64_t)normalized_shape.size();
  TORCH_CHECK(nn >= 1, "normalized_shape must be non-empty");
  TORCH_CHECK(ndim >= nn, "x.dim() must be >= len(normalized_shape)");

  int64_t N = 1;
  for (int64_t i = 0; i < nn; ++i) {
    TORCH_CHECK(x.size(ndim - nn + i) == normalized_shape[i],
                "x trailing dims must match normalized_shape");
    N *= normalized_shape[i];
  }
  TORCH_CHECK(N > 0, "normalized numel must be > 0");
  const int64_t R = x.numel() / N;
  TORCH_CHECK(R >= 1 && R <= 65535, "rows out of supported range");

  const c10::cuda::CUDAGuard device_guard(x.device());
  auto x_c = x.contiguous();

  torch::Tensor w_c, b_c;
  const float* w_ptr = nullptr;
  const float* b_ptr = nullptr;
  if (weight.has_value() && weight->defined()) {
    TORCH_CHECK(weight->is_cuda() && weight->scalar_type() == at::kFloat, "bad weight");
    TORCH_CHECK(weight->numel() == N, "weight numel mismatch");
    w_c = weight->contiguous();
    w_ptr = w_c.data_ptr<float>();
  }
  if (bias.has_value() && bias->defined()) {
    TORCH_CHECK(bias->is_cuda() && bias->scalar_type() == at::kFloat, "bad bias");
    TORCH_CHECK(bias->numel() == N, "bias numel mismatch");
    b_c = bias->contiguous();
    b_ptr = b_c.data_ptr<float>();
  }

  auto y = torch::empty_like(x_c);

  auto f64 = torch::TensorOptions().dtype(torch::kFloat64).device(x_c.device());
  auto i32 = torch::TensorOptions().dtype(torch::kInt32).device(x_c.device());
  auto d_sum   = torch::zeros({R}, f64);
  auto d_sumsq = torch::zeros({R}, f64);
  auto d_count = torch::zeros({R}, i32);

  int dev = x_c.get_device();
  int numSMs = 0;
  cudaDeviceGetAttribute(&numSMs, cudaDevAttrMultiProcessorCount, dev);
  TORCH_CHECK(numSMs > 0, "could not query SM count");

  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

  const float* X = x_c.data_ptr<float>();
  float* Y = y.data_ptr<float>();

  bool aligned16 = ((N & 3) == 0) &&
      ((reinterpret_cast<uintptr_t>(X) & 15) == 0) &&
      ((reinterpret_cast<uintptr_t>(Y) & 15) == 0) &&
      (w_ptr == nullptr || (reinterpret_cast<uintptr_t>(w_ptr) & 15) == 0) &&
      (b_ptr == nullptr || (reinterpret_cast<uintptr_t>(b_ptr) & 15) == 0);

