cuda_src = r"""
#include <torch/extension.h>
#include <c10/cuda/CUDAStream.h>
#include <c10/cuda/CUDAGuard.h>
#include <cuda_runtime.h>
#include <cute/tensor.hpp>
#include <type_traits>
#include <vector>

using namespace cute;

// Single fused LayerNorm kernel.
// Grid: (splits, rows). Each block reduces a contiguous chunk of one row,
// atomically accumulates partial sums, synchronizes across the splits of its
// row (all blocks are guaranteed co-resident because the grid is clamped to
// the occupancy limit), then normalizes its chunk with the final mean/rstd.
template <typename T, typename VecT, int TPB>
__global__ void layernorm_rows_kernel(
    const T* __restrict__ X,
    const T* __restrict__ W,
    const T* __restrict__ B,
    T* __restrict__ Y,
    double* __restrict__ d_sum,
    double* __restrict__ d_sumsq,
    int*   __restrict__ d_count,
    int64_t Ne,     // number of VecT elements per row
    int64_t chunk,  // VecT elements per split (multiple of TPB)
    int64_t N,      // number of scalars per row
    float eps)
{
  constexpr int V = (int)(sizeof(VecT) / sizeof(T));

  const int row    = blockIdx.y;
  const int split  = blockIdx.x;
  const int nsplit = gridDim.x;
  const int tid    = threadIdx.x;

  const VecT* xrow = reinterpret_cast<const VecT*>(X + (int64_t)row * N);
  VecT*       yrow = reinterpret_cast<VecT*>(Y + (int64_t)row * N);

  // CuTe global tensors (row views)
  Tensor gX = make_tensor(make_gmem_ptr(xrow), make_shape(Ne), make_stride(Int<1>{}));
  Tensor gY = make_tensor(make_gmem_ptr(yrow), make_shape(Ne), make_stride(Int<1>{}));
  Tensor gW = make_tensor(make_gmem_ptr(reinterpret_cast<const VecT*>(W)),
                          make_shape(Ne), make_stride(Int<1>{}));
  Tensor gB = make_tensor(make_gmem_ptr(reinterpret_cast<const VecT*>(B)),
                          make_shape(Ne), make_stride(Int<1>{}));

  const int64_t begin = (int64_t)split * chunk;
  int64_t end = begin + chunk;
  if (end > Ne) end = Ne;

  __shared__ double rs[TPB];
  __shared__ double rq[TPB];
  __shared__ double s_mean, s_rstd;

  // ---- Phase 1: partial reduction (double accumulation for stability) ----
  double s = 0.0, q = 0.0;
  for (int64_t i = begin + tid; i < end; i += TPB) {
    VecT v = gX(i);
    if constexpr (V == 4) {
      double x0 = (double)v.x;
      double x1 = (double)v.y;
      double x2 = (double)v.z;
      double x3 = (double)v.w;
      s += (x0 + x1) + (x2 + x3);
      q += (x0 * x0 + x1 * x1) + (x2 * x2 + x3 * x3);
    } else {
      double x0 = (double)v;
      s += x0;
      q += x0 * x0;
    }
  }

  // Block tree reduction
  rs[tid] = s;
  rq[tid] = q;
  __syncthreads();
  #pragma unroll
  for (int off = TPB / 2; off > 0; off >>= 1) {
    if (tid < off) {
      rs[tid] += rs[tid + off];
      rq[tid] += rq[tid + off];
    }
    __syncthreads();
  }

  // Cross-split accumulation + synchronization for this row
  if (tid == 0) {
    atomicAdd(&d_sum[row], rs[0]);
    atomicAdd(&d_sumsq[row], rq[0]);
    __threadfence();
    atomicAdd(&d_count[row], 1);
    while (atomicAdd(&d_count[row], 0) < nsplit) { }
    __threadfence();
    double sum  = __ldcg(d_sum + row);
    double sumq = __ldcg(d_sumsq + row);
    double mean = sum / (double)N;
    double var  = sumq / (double)N - mean * mean;
    if (var < 0.0) var = 0.0;
    s_mean = mean;
    s_rstd = rsqrt(var + (double)eps);
  }
  __syncthreads();

  const float fmean = (float)s_mean;
  const float frstd = (float)s_rstd;

  // ---- Phase 2: normalize + optional affine ----
  for (int64_t i = begin + tid; i < end; i += TPB) {
    VecT xv = gX(i);
    VecT yv;
    if constexpr (V == 4) {
      float wx = 1.0f, wy = 1.0f, wz = 1.0f, ww = 1.0f;
      float bx = 0.0f, by = 0.0f, bz = 0.0f, bw = 0.0f;
      if (W != nullptr) {
        float4 wv = gW(i);
        wx = wv.x; wy = wv.y; wz = wv.z; ww = wv.w;
      }
      if (B != nullptr) {
        float4 bv = gB(i);
        bx = bv.x; by = bv.y; bz = bv.z; bw = bv.w;
      }
      yv.x = ((float)xv.x - fmean) * frstd * wx + bx;
      yv.y = ((float)xv.y - fmean) * frstd * wy + by;
      yv.z = ((float)xv.z - fmean) * frstd * wz + bz;
      yv.w = ((float)xv.w - fmean) * frstd * ww + bw;
    } else {
      float w0 = 1.0f, b0 = 0.0f;
      if (W != nullptr) w0 = (float)gW(i);
      if (B != nullptr) b0 = (float)gB(i);
      yv = ((float)xv - fmean) * frstd * w0 + b0;
    }
    gY(i) = yv;
  }
}

template <typename VecT>
static void launch_layernorm(
    const float* X, const float* W, const float* B, float* Y,
    double* d_sum, double* d_sumsq, int* d_count,
    int64_t N, int64_t R, float eps, int numSMs, cudaStream_t stream)
{
  constexpr int TPB = 256;
  constexpr int V = (int)(sizeof(VecT) / sizeof(float));
  const int64_t Ne = N / V;

  auto kfn = layernorm_rows_kernel<float, VecT, TPB>;
  int bpsm = 0;
  cudaError_t oerr = cudaOccupancyMaxActiveBlocksPerMultiprocessor(&bpsm, kfn, TPB, 0);
  TORCH_CHECK(oerr == cudaSuccess, "occupancy query failed: ", cudaGetErrorString(oerr));
  if (bpsm < 1) bpsm = 1;

  // Clamp grid so all blocks are co-resident (required for the spin sync).
  int64_t maxResident = (int64_t)bpsm * (int64_t)numSMs;
  int64_t S = maxResident / R;
  if (S < 1) S = 1;
  int64_t Smax = (Ne + TPB - 1) / TPB;
  if (Smax < 1) Smax = 1;
  if (S > Smax) S = Smax;

  int64_t chunk = (Ne + S - 1) / S;
  chunk = ((chunk + TPB - 1) / TPB) * (int64_t)TPB;
  int64_t Seff = (Ne + chunk - 1) / chunk;

  dim3 grid((unsigned)Seff, (unsigned)R);
  dim3 block(TPB);
  kfn<<<grid, block, 0, stream>>>(X, W, B, Y, d_sum, d_sumsq, d_count,
                                  Ne, chunk, N, eps);
}

